package com.bookeat.dining.service;
import com.bookeat.diniticket.service.*;import com.bookeat.diniticket.entity.DiniTicket;import com.bookeat.dining.repository.DiningSessionRepository;import com.bookeat.dining.entity.DiningSession;import com.bookeat.dining.enums.*;import com.bookeat.order.service.OrderLifecycleGuard;import com.bookeat.order.repository.FoodOrderRepository;import com.bookeat.exception.*;
import org.springframework.stereotype.Component;import org.springframework.transaction.annotation.*;import lombok.RequiredArgsConstructor;import java.util.*;import java.time.Clock;import java.math.BigDecimal;
@Component @RequiredArgsConstructor @Transactional(propagation=Propagation.MANDATORY)
public class DiningLifecycleBridge implements TicketSeatingObserver,TicketCommitmentGuard,OrderLifecycleGuard {
 private final DiningSessionRepository sessions;private final FoodOrderRepository orders;private final List<DiningPaymentPort> payments;private final Clock clock;
 public void seated(DiniTicket t,UUID actor){if(sessions.findByDiniTicketId(t.getId()).isPresent())return;var d=new DiningSession();d.setDiniTicketId(t.getId());d.setCustomerId(t.getCustomerId());d.setRestaurantId(t.getRestaurantId());d.setTableId(t.getTableId());d.setStatus(DiningStatus.DINING);d.setCheckInMethod(CheckInMethod.DINITICKET_SEATING);d.setCheckedInAt(clock.instant());d.setDiningStartedAt(clock.instant());d.setBillTotal(BigDecimal.ZERO);sessions.saveAndFlush(d);}
 public void beforeCreate(UUID reservation,UUID ticket){var d=reservation!=null?sessions.findByReservationId(reservation):ticket!=null?sessions.findByDiniTicketId(ticket):Optional.<DiningSession>empty();if(d.isPresent()&&!DiningRules.canOrder(d.get().getStatus()))throw new ApiException(ErrorCode.DINING_STATE_INVALID);}
 public boolean mayExpire(UUID ticket){return true;} public void beforeCancel(UUID ticket,UUID actor){}
 public void beforeComplete(UUID ticket){var d=sessions.findByDiniTicketId(ticket);if(d.isEmpty()||d.get().getStatus()==DiningStatus.CHECKED_OUT)return;boolean hasDue=orders.findByDiniTicketId(ticket).stream().anyMatch(o->o.getTotal().signum()>0&&o.getStatus()!=com.bookeat.order.enums.FoodOrderStatus.CANCELLED&&o.getStatus()!=com.bookeat.order.enums.FoodOrderStatus.REJECTED);if(hasDue&&(payments.isEmpty()||payments.stream().anyMatch(p->!p.settled(null,ticket))))throw new ApiException(ErrorCode.PAYMENT_REQUIRED);d.get().setStatus(DiningStatus.CHECKED_OUT);d.get().setCheckedOutAt(clock.instant());d.get().setPaidAt(clock.instant());}
}
